document.addEventListener("DOMContentLoaded",init);async function init(){const owner=await Auth.guardOwnerAuth();if(!owner)return;if(!owner.isAdmin){document.getElementById("admin-denied").classList.remove("hidden");return}document.getElementById("admin-tools").classList.remove("hidden");await loadStores();document.getElementById("feature-store-btn").addEventListener("click",onFeatureStore);document.getElementById("prod-store-select").addEventListener("change",onPickStoreForProduct);document.getElementById("feature-product-btn").addEventListener("click",onFeatureProduct);document.getElementById("badge-recompute-btn").addEventListener("click",onRecomputeBadges);loadFeatured();loadSellerBadges()}async function loadStores(){const res=await Api.get("listStores",{});const stores=res.ok?res.stores||[]:[];const opts=['<option value="">Choose a store…</option>'].concat(stores.map(s=>`<option value="${escapeHtml(s.storeSlug)}">${escapeHtml(s.storeName)}</option>`)).join("");document.getElementById("store-select").innerHTML=opts;document.getElementById("prod-store-select").innerHTML=opts}async function onPickStoreForProduct(){const slug=document.getElementById("prod-store-select").value;const sel=document.getElementById("product-select");if(!slug){sel.innerHTML='<option value="">Choose a store first…</option>';return}sel.innerHTML='<option value="">Loading…</option>';const res=await Api.get("listProducts",{storeSlug:slug});const products=res.ok?res.products||[]:[];sel.innerHTML=['<option value="">Choose a product…</option>'].concat(products.map(p=>`<option value="${escapeHtml(p.productId)}">${escapeHtml(p.name)}</option>`)).join("")}function onFeatureStore(){const slug=document.getElementById("store-select").value;if(slug)addFeatured("store",slug)}function onFeatureProduct(){const pid=document.getElementById("product-select").value;if(pid)addFeatured("product",pid)}async function addFeatured(type,refId){const errorEl=document.getElementById("admin-error");errorEl.textContent="";const res=await Api.post("addFeatured",{token:Auth.getToken(),type:type,refId:refId});if(!res.ok){errorEl.textContent=res.error||"Could not add that item.";return}loadFeatured()}async function loadFeatured(){const statusEl=document.getElementById("featured-status");const listEl=document.getElementById("featured-list");const stop=startLoadingMessage(statusEl);const res=await Api.post("listFeatured",{token:Auth.getToken()});stop();if(!res.ok){listEl.innerHTML="";showLoadFailedMessage(statusEl);return}const items=res.featured||[];if(items.length===0){listEl.innerHTML="";statusEl.textContent="Nothing featured yet.";return}statusEl.textContent="";listEl.innerHTML=items.map(featuredRow).join("");listEl.querySelectorAll("[data-remove]").forEach(btn=>{btn.addEventListener("click",()=>onRemove(btn.dataset.remove))})}function featuredRow(f){return`\n    <div class="dash-item">\n      <div class="dash-item-main">\n        <strong>${escapeHtml(f.label)}</strong>\n        <span class="helper-text">${escapeHtml(f.type)}</span>\n      </div>\n      <div class="dash-item-side">\n        <button type="button" class="btn btn-small btn-danger" data-remove="${escapeHtml(f.featuredId)}">Remove</button>\n      </div>\n    </div>`}async function onRemove(featuredId){const res=await Api.post("removeFeatured",{token:Auth.getToken(),featuredId:featuredId});if(res.ok)loadFeatured()}let badgeSellers=[];let badgeConfigValues={};async function loadSellerBadges(){const statusEl=document.getElementById("badge-status");const listEl=document.getElementById("badge-seller-list");const stop=startLoadingMessage(statusEl);const res=await Api.post("listSellerBadges",{token:Auth.getToken()});stop();if(!res.ok){listEl.innerHTML="";showLoadFailedMessage(statusEl);return}badgeSellers=res.sellers||[];badgeConfigValues=res.config||{};statusEl.textContent=badgeSellers.length?"":"No stores yet.";const stamped=badgeSellers.map(s=>s.updatedAt).filter(Boolean).sort();document.getElementById("badge-updated").textContent=stamped.length?"Last worked out "+new Date(stamped[stamped.length-1]).toLocaleString():"Not worked out yet — press Recompute now.";listEl.innerHTML=badgeSellers.map(sellerBadgeRowHtml).join("");wireSellerBadgeControls();renderBadgeConfig()}function sellerBadgeRowHtml(s){const chip=ids=>typeof renderSellerBadges==="function"?renderSellerBadges(ids,{size:"chip",interactive:false}):"";const shown=s.badges.length?s.badges.map(id=>`\n        <div class="badge-admin-item">\n          ${chip([id])}\n          <span class="badge-admin-source badge-admin-source--${s.source[id]==="admin"?"admin":"auto"}">\n            ${s.source[id]==="admin"?"ADMIN OVERRIDE":"AUTO AWARDED"}\n          </span>\n          ${s.why[id]?`<span class="helper-text badge-admin-why">${escapeHtml(s.why[id])}</span>`:""}\n        </div>`).join(""):'<p class="helper-text">No badges.</p>';const withheld=(s.autoBadges||[]).filter(id=>s.badges.indexOf(id)===-1);const withheldHtml=withheld.length?`<div class="badge-admin-item badge-admin-item--withheld">\n         ${chip(withheld)}\n         <span class="badge-admin-source badge-admin-source--withheld">EARNED, NOT SHOWN</span>\n         <span class="helper-text badge-admin-why">${s.suppressed?"This store is hidden from all badges.":"Removed by an admin."}</span>\n       </div>`:"";const m=s.metrics||{};const figure=(label,value)=>`<span><strong>${escapeHtml(String(value))}</strong> ${label}</span>`;return`\n    <div class="dash-item badge-admin-row" data-owner-id="${escapeHtml(s.ownerId)}">\n      <div class="badge-admin-head">\n        <strong>${escapeHtml(s.storeName||s.storeSlug)}</strong>\n        <span class="helper-text">${escapeHtml(s.storeSlug)}${s.status&&s.status!=="active"?" · "+escapeHtml(s.status):""}</span>\n      </div>\n\n      <p class="helper-text badge-admin-figures">\n        ${s.score===null?"<span>Not enough data to score</span>":figure("score",s.score)}\n        ${figure("orders",m.orders||0)}\n        ${figure("fulfilled",m.fulfilled||0)}\n        ${figure("cancelled",m.cancelled||0)}\n        ${figure("reviews",m.reviews||0)}\n        ${m.rating!=null?figure("average",m.rating):""}\n        ${m.medianReplyMinutes!=null?figure("min median reply",m.medianReplyMinutes):""}\n        ${figure("repeat customers",m.repeatCustomers||0)}\n      </p>\n\n      <div class="badge-admin-badges">${shown}${withheldHtml}</div>\n\n      <div class="badge-admin-controls">\n        ${overrideControl(s,"verified","Verified Seller")}\n        ${overrideControl(s,"recommended","Mwakete Recommended")}\n        <label class="badge-admin-suppress">\n          <input type="checkbox" data-badge-suppress ${s.suppressed?"checked":""}>\n          Hide all badges for this store\n        </label>\n      </div>\n    </div>`}function overrideControl(s,field,label){const current=s.overrides[field]||"";const opt=(v,text)=>`<option value="${v}"${current===v?" selected":""}>${text}</option>`;return`\n    <label class="badge-admin-override">\n      <span>${escapeHtml(label)}</span>\n      <select data-badge-field="${field}">\n        ${opt("","Automatic")}\n        ${opt("true","Granted")}\n        ${opt("false","Removed")}\n      </select>\n    </label>`}function wireSellerBadgeControls(){document.querySelectorAll(".badge-admin-row").forEach(row=>{const ownerId=row.dataset.ownerId;row.querySelectorAll("[data-badge-field]").forEach(sel=>{sel.addEventListener("change",()=>setBadgeOverride(ownerId,sel.dataset.badgeField,sel.value,sel))});const box=row.querySelector("[data-badge-suppress]");if(box){box.addEventListener("change",()=>setBadgeOverride(ownerId,"suppressed",box.checked?"true":"",box))}})}async function setBadgeOverride(ownerId,field,value,control){const errorEl=document.getElementById("badge-error");errorEl.textContent="";control.disabled=true;const res=await Api.post("setSellerBadgeOverride",{token:Auth.getToken(),ownerId:ownerId,field:field,value:value});control.disabled=false;if(!res.ok){errorEl.textContent=res.error||"Could not change that.";return}loadSellerBadges()}function renderBadgeConfig(){const el=document.getElementById("badge-config-list");if(!el)return;const keys=Object.keys(badgeConfigValues).sort();el.innerHTML=keys.map(key=>{const value=badgeConfigValues[key];const isFlag=value==="true"||value==="false";const id="cfg-"+key.replace(/[^a-z0-9]/gi,"-");const input=isFlag?`<select id="${id}" data-config-key="${escapeHtml(key)}">\n           <option value="true"${value==="true"?" selected":""}>On</option>\n           <option value="false"${value==="false"?" selected":""}>Off</option>\n         </select>`:`<input id="${id}" type="number" step="any" min="0"\n           data-config-key="${escapeHtml(key)}" value="${escapeHtml(String(value))}">`;return`<div class="field badge-config-field">\n        <label for="${id}">${escapeHtml(key)}</label>\n        ${input}\n      </div>`}).join("");el.querySelectorAll("[data-config-key]").forEach(input=>{input.addEventListener("change",()=>saveBadgeConfig(input))})}async function saveBadgeConfig(input){const errorEl=document.getElementById("badge-error");errorEl.textContent="";input.disabled=true;const res=await Api.post("setBadgeConfig",{token:Auth.getToken(),key:input.dataset.configKey,value:input.value});input.disabled=false;if(!res.ok){errorEl.textContent=res.error||"Could not save that setting.";return}loadSellerBadges()}async function onRecomputeBadges(){const btn=document.getElementById("badge-recompute-btn");const errorEl=document.getElementById("badge-error");errorEl.textContent="";btn.disabled=true;btn.textContent="Working…";const res=await Api.post("recomputeBadges",{token:Auth.getToken()});btn.disabled=false;btn.textContent="Recompute now";if(!res.ok){errorEl.textContent=res.error||"Could not recompute.";return}loadSellerBadges()}